void write(json::Writer& w, const InstalledApp& value)
{
    w.begin_object();
    w.key("app_id");
    w.string(value.app_id);
    w.key("version_code");
    w.number(value.version_code);
    w.end_object();
}

void write(json::Writer& w, const MissingRequest& value)
{
    w.begin_object();
    w.key("schema");
    w.number(std::uint64_t{1});
    w.key("installed");
    w.begin_array();
    for (const auto& item : value.installed)
    {
        write(w, item);
    }
    w.end_array();
    w.key("want");
    w.begin_array();
    for (const auto& item : value.want)
    {
        w.string(item);
    }
    w.end_array();
    w.end_object();
}

void write(json::Writer& w, const InstalledHomebrew& value)
{
    w.begin_object();
    w.key("id");
    w.string(value.id);
    w.key("build");
    w.number(value.build);
    w.end_object();
}

void write(json::Writer& w, const HomebrewUpdatesRequest& value)
{
    w.begin_object();
    w.key("schema");
    w.number(std::uint64_t{1});
    w.key("installed");
    w.begin_array();
    for (const auto& item : value.installed)
    {
        write(w, item);
    }
    w.end_array();
    w.end_object();
}

void write_missing_request(const MissingRequest& value, String& out)
{
    json::Writer w(out);
    write(w, value);
}

void write_homebrew_updates_request(const HomebrewUpdatesRequest& value, String& out)
{
    json::Writer w(out);
    write(w, value);
}

